proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
{
    // Unfold `valid` and `implies`:
    // We need: forall ex, always(p.and(q))(ex) ==> always(p)(ex) && always(q)(ex)
    assert forall |ex: Execution<T>| #[trigger]
        always(p.and(q)).satisfied_by(ex) ==> (always(p).satisfied_by(ex) && always(q).satisfied_by(ex)) by {
        // From the assumption, get the `p.and(q)` fact at every suffix.
        assert forall |i: nat| #[trigger] (p.and(q)).satisfied_by(ex.suffix(i)) by {
            assert always(p.and(q)).satisfied_by(ex);
            // `always(p.and(q)).satisfied_by(ex)` is definitionally `forall i. (p.and(q))(ex.suffix(i))`
        };

        // Prove `always(p)`.
        assert always(p).satisfied_by(ex) by {
            assert forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i));
            // For any i, since (p.and(q))(ex.suffix(i)) holds, p holds too.
        };

        // Prove `always(q)`.
        assert always(q).satisfied_by(ex) by {
            assert forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i));
        };
    };

    // Package the goal back into the required form.
    assert(valid(always(p.and(q)).implies(always(p).and(always(q)))));
}

