proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
{
    // `valid(r)` unfolds to `forall ex. r.satisfied_by(ex)`.
    // Here `r = always(p.and(q)).implies(always(p).and(always(q)))`.
    reveal(valid);
    reveal(TempPred::implies);

    // So it suffices to prove the pointwise implication.
    assert forall |ex: Execution<T>| #[trigger]
        always(p.and(q)).satisfied_by(ex) ==> always(p).and(always(q)).satisfied_by(ex) by {
        if always(p.and(q)).satisfied_by(ex) {
            // Unfold `always` to get the pointwise fact on suffixes.
            reveal(always);

            // Unfold `and`/`satisfied_by` so that we can split `(p.and(q))`.
            reveal(TempPred::and);
            reveal(TempPred::satisfied_by);

            // Prove `always(p)` at `ex`.
            assert forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i)) by {
                // From the assumption and unfolding of `always`, we have `(p.and(q)).satisfied_by(ex.suffix(i))`.
                assert((p.and(q)).satisfied_by(ex.suffix(i)));
                // Therefore the left conjunct holds.
                assert(p.satisfied_by(ex.suffix(i)));
            };

            // Prove `always(q)` at `ex`.
            assert forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i)) by {
                assert((p.and(q)).satisfied_by(ex.suffix(i)));
                assert(q.satisfied_by(ex.suffix(i)));
            };

            // Combine into the goal.
            assert(always(p).satisfied_by(ex) && always(q).satisfied_by(ex));
        }
    };
}

